-- No account, CRM, payment, review or business fixture data is seeded.
CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email_canonical text NOT NULL UNIQUE CHECK(length(email_canonical)<=254 AND email_canonical=lower(email_canonical)),
 password_phc text NOT NULL CHECK(password_phc LIKE '$argon2id$%' AND length(password_phc)<=1024),
 display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 100), email_verified_at timestamptz,
 status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deletion_pending')),
 security_version integer NOT NULL DEFAULT 1 CHECK(security_version>0), version integer NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE user_roles(user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('super-admin','admin','moderator','content-manager','business-manager','support','business-owner','user')), PRIMARY KEY(user_id,role));
CREATE TABLE account_consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),document text NOT NULL CHECK(document IN ('terms','privacy','platform_review_publication')),version text NOT NULL CHECK(length(version) BETWEEN 1 AND 80),accepted_at timestamptz NOT NULL DEFAULT now(),withdrawn_at timestamptz);
CREATE INDEX account_consents_owner ON account_consents(user_id,accepted_at,id);
CREATE TABLE auth_sessions(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_digest text NOT NULL UNIQUE CHECK(token_digest ~ '^[0-9a-f]{64}$'),csrf_digest text NOT NULL CHECK(csrf_digest ~ '^[0-9a-f]{64}$'),
 assurance text NOT NULL CHECK(assurance IN ('password','mfa','recovery')),security_version integer NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),idle_expires_at timestamptz NOT NULL,absolute_expires_at timestamptz NOT NULL,step_up_until timestamptz,revoked_at timestamptz,
 CHECK(idle_expires_at<=absolute_expires_at AND created_at<absolute_expires_at)
);
CREATE INDEX auth_sessions_owner ON auth_sessions(user_id,created_at,id);
CREATE INDEX auth_sessions_expiry ON auth_sessions(idle_expires_at) WHERE revoked_at IS NULL;
CREATE TABLE auth_challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('preauth','login','enrollment','reset','email-verification')),token_digest text NOT NULL UNIQUE CHECK(token_digest ~ '^[0-9a-f]{64}$'),csrf_digest text NOT NULL CHECK(csrf_digest ~ '^[0-9a-f]{64}$'),encrypted_secret jsonb,expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(kind='preauth' OR user_id IS NOT NULL));
CREATE INDEX auth_challenges_expiry ON auth_challenges(expires_at);
CREATE TABLE mfa_credentials(user_id uuid PRIMARY KEY REFERENCES users(id),encrypted_secret jsonb NOT NULL CHECK(jsonb_typeof(encrypted_secret)='object' AND encrypted_secret ?& ARRAY['keyId','nonce','tag','ciphertext']),last_used_step bigint NOT NULL DEFAULT -1,enrolled_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recovery_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),digest text NOT NULL CHECK(length(digest) BETWEEN 32 AND 1024),consumed_at timestamptz,UNIQUE(user_id,digest));
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users(id),action text NOT NULL CHECK(action ~ '^[a-z][a-z0-9_.:-]{0,99}$'),resource_type text NOT NULL CHECK(length(resource_type) BETWEEN 1 AND 80),resource_id text NOT NULL CHECK(length(resource_id) BETWEEN 1 AND 200),changed_fields text[] NOT NULL DEFAULT '{}',outcome text NOT NULL DEFAULT 'success' CHECK(outcome IN ('success','denied','failure')),request_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_resource ON audit_events(resource_type,resource_id,created_at,id);
CREATE INDEX audit_actor ON audit_events(actor_id,created_at,id);
CREATE FUNCTION reject_immutable_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable record'; END $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
-- Serialize role/status changes, including direct SQL, to preserve last active super-admin.
CREATE FUNCTION guard_last_superadmin() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(745912,3);
 IF TG_TABLE_NAME='user_roles' THEN
  IF OLD.role='super-admin' AND NOT EXISTS(SELECT 1 FROM user_roles r JOIN users u ON u.id=r.user_id WHERE r.role='super-admin' AND u.status='active' AND r.user_id<>OLD.user_id) THEN RAISE EXCEPTION 'last active super-admin'; END IF;
 ELSE
  IF OLD.status='active' AND NEW.status<>'active' AND EXISTS(SELECT 1 FROM user_roles WHERE user_id=OLD.id AND role='super-admin') AND NOT EXISTS(SELECT 1 FROM user_roles r JOIN users u ON u.id=r.user_id WHERE r.role='super-admin' AND u.status='active' AND u.id<>OLD.id) THEN RAISE EXCEPTION 'last active super-admin'; END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
CREATE TRIGGER last_superadmin_role BEFORE DELETE OR UPDATE ON user_roles FOR EACH ROW EXECUTE FUNCTION guard_last_superadmin();
CREATE TRIGGER last_superadmin_status BEFORE UPDATE OF status ON users FOR EACH ROW EXECUTE FUNCTION guard_last_superadmin();
CREATE TABLE businesses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE business_memberships(user_id uuid NOT NULL REFERENCES users(id),business_id uuid NOT NULL REFERENCES businesses(id),active boolean NOT NULL DEFAULT false,verified_at timestamptz,PRIMARY KEY(user_id,business_id),CHECK(NOT active OR verified_at IS NOT NULL));
CREATE TABLE business_branches(place_id uuid PRIMARY KEY REFERENCES places(id),business_id uuid NOT NULL REFERENCES businesses(id),version integer NOT NULL DEFAULT 1);
CREATE INDEX business_branches_business ON business_branches(business_id,place_id);
CREATE TABLE owner_crm(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid UNIQUE REFERENCES users(id),display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 100),notes text CHECK(length(notes)<=2000),phone_encrypted jsonb CHECK(phone_encrypted IS NULL OR (jsonb_typeof(phone_encrypted)='object' AND phone_encrypted ?& ARRAY['keyId','nonce','tag','ciphertext'])),version integer NOT NULL DEFAULT 1,archived_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE listing_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),applicant_id uuid NOT NULL REFERENCES users(id),place_id uuid NOT NULL REFERENCES places(id),version integer NOT NULL DEFAULT 1,source_state text NOT NULL CHECK(source_state IN ('public-source','business-submitted')),ownership_state text NOT NULL DEFAULT 'unclaimed' CHECK(ownership_state IN ('unclaimed','pending','verified','revoked')),placement_state text NOT NULL DEFAULT 'pending-quote' CHECK(placement_state IN ('pending-quote','pending-payment','pending-review','published','rejected','withdrawn')),payment_state text NOT NULL DEFAULT 'not-requested' CHECK(payment_state IN ('not-requested','pending','manually-confirmed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX listing_owner ON listing_applications(applicant_id,created_at,id);
CREATE TABLE listing_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listing_applications(id),amount_rub integer NOT NULL CHECK(amount_rub>0),terms text NOT NULL CHECK(length(terms) BETWEEN 10 AND 3000),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER quote_immutable BEFORE UPDATE OR DELETE ON listing_quotes FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
CREATE TABLE manual_subscription_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listing_applications(id),quote_id uuid NOT NULL REFERENCES listing_quotes(id),receipt_reference text NOT NULL UNIQUE CHECK(length(receipt_reference) BETWEEN 10 AND 200),amount_rub integer NOT NULL CHECK(amount_rub>0),currency text NOT NULL CHECK(currency='RUB'),received_at timestamptz NOT NULL,period_starts_at timestamptz NOT NULL,period_ends_at timestamptz NOT NULL,idempotency_key uuid NOT NULL UNIQUE,payload_hash text NOT NULL CHECK(payload_hash ~ '^[0-9a-f]{64}$'),confirmed_by uuid NOT NULL REFERENCES users(id),audit_id uuid NOT NULL REFERENCES audit_events(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(listing_id,period_starts_at),CHECK(period_starts_at<period_ends_at));
CREATE TRIGGER payment_immutable BEFORE UPDATE OR DELETE ON manual_subscription_payments FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
CREATE TABLE cms_documents(key text PRIMARY KEY CHECK(key IN ('homepage','about','faq','contacts','terms','privacy','pricing','site-settings','brand')),current_version integer NOT NULL DEFAULT 0 CHECK(current_version>=0),published_revision_id uuid);
CREATE TABLE cms_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text NOT NULL REFERENCES cms_documents(key),version integer NOT NULL CHECK(version>0),document jsonb NOT NULL CHECK(jsonb_typeof(document)='object' AND octet_length(document::text)<=16000),author_id uuid NOT NULL REFERENCES users(id),change_note text NOT NULL CHECK(length(change_note) BETWEEN 5 AND 500),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(key,version),UNIQUE(key,id));
ALTER TABLE cms_documents ADD FOREIGN KEY(key,published_revision_id) REFERENCES cms_revisions(key,id);
CREATE TABLE cms_publications(revision_id uuid PRIMARY KEY REFERENCES cms_revisions(id),published_at timestamptz NOT NULL DEFAULT now(),actor_id uuid NOT NULL REFERENCES users(id),audit_id uuid NOT NULL REFERENCES audit_events(id));
CREATE TRIGGER cms_revision_immutable BEFORE UPDATE OR DELETE ON cms_revisions FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
CREATE TABLE media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),purpose text NOT NULL CHECK(purpose IN ('logo','content-image','business-photo')),state text NOT NULL DEFAULT 'awaiting-upload' CHECK(state IN ('awaiting-upload','ready','archived')),storage_key text UNIQUE,mime text NOT NULL CHECK(mime IN ('image/jpeg','image/png','image/webp')),byte_length integer NOT NULL CHECK(byte_length BETWEEN 1 AND 2097152),sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'),width integer CHECK(width BETWEEN 1 AND 4096),height integer CHECK(height BETWEEN 1 AND 4096),attribution text NOT NULL CHECK(length(attribution) BETWEEN 1 AND 500),license text NOT NULL CHECK(length(license) BETWEEN 1 AND 200),rights_confirmed_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(width IS NULL OR height IS NULL OR width*height<=16000000),CHECK(state<>'ready' OR (storage_key IS NOT NULL AND width IS NOT NULL AND height IS NOT NULL AND mime='image/webp')));
ALTER TABLE places ADD COLUMN version integer NOT NULL DEFAULT 1 CHECK(version>0);
CREATE TABLE place_admin_metadata(place_id uuid PRIMARY KEY REFERENCES places(id),street text NOT NULL CHECK(length(street) BETWEEN 1 AND 200),house text CHECK(length(house)<=80),photos jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(photos)='array'),provenance jsonb NOT NULL CHECK(jsonb_typeof(provenance)='array' AND jsonb_array_length(provenance)>0),status text NOT NULL CHECK(status IN ('draft','published','archived')),editor_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL CHECK(length(reason) BETWEEN 10 AND 1000),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE place_field_overrides(place_id uuid NOT NULL REFERENCES places(id),field text NOT NULL CHECK(field IN ('name','cityId','categoryIds','address','coordinates','description','phone','website','openingHours','accessibility','active')),editor_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL CHECK(length(reason) BETWEEN 10 AND 1000),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(place_id,field));
CREATE TABLE account_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),author_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('place','platform')),place_id uuid REFERENCES places(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),original_text text NOT NULL CHECK(length(original_text) BETWEEN 10 AND 3000),text text NOT NULL CHECK(length(text) BETWEEN 10 AND 3000),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','published','rejected','deleted')),version integer NOT NULL DEFAULT 1,consent_id uuid REFERENCES account_consents(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,CHECK((kind='place')=(place_id IS NOT NULL)),CHECK(kind<>'platform' OR consent_id IS NOT NULL),CHECK(status<>'published' OR published_at IS NOT NULL));
CREATE UNIQUE INDEX review_place_author ON account_reviews(author_id,place_id) WHERE status<>'deleted' AND kind='place';
CREATE UNIQUE INDEX review_platform_author ON account_reviews(author_id) WHERE status<>'deleted' AND kind='platform';
CREATE INDEX review_public ON account_reviews(place_id,published_at,id) WHERE status='published';
CREATE INDEX review_owner ON account_reviews(author_id,updated_at,id);
CREATE TABLE review_corrections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),review_id uuid NOT NULL REFERENCES account_reviews(id),author_id uuid NOT NULL REFERENCES users(id),original_text text NOT NULL,corrected_text text NOT NULL CHECK(length(corrected_text) BETWEEN 10 AND 3000),editor_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL CHECK(length(reason) BETWEEN 10 AND 1000),version integer NOT NULL,audit_id uuid NOT NULL REFERENCES audit_events(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(review_id,version),CHECK(author_id<>editor_id));
CREATE TRIGGER correction_immutable BEFORE UPDATE OR DELETE ON review_corrections FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
INSERT INTO data_sources(id,name,license,attribution,enabled) VALUES('patchvale-admin','Patchvale — operator supplied records','Operator-confirmed rights','Patchvale operator-provided source evidence',true);
ALTER TABLE place_admin_metadata ADD COLUMN draft_organization jsonb NOT NULL,
 ADD COLUMN published_organization jsonb,ADD COLUMN published_provenance jsonb,ADD COLUMN published_photos jsonb,ADD COLUMN published_at timestamptz;
CREATE TABLE owner_business_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owner_crm(id),place_id uuid NOT NULL REFERENCES places(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,place_id));
CREATE TABLE founder_agreements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listing_applications(id),quote_id uuid NOT NULL UNIQUE REFERENCES listing_quotes(id),owner_id uuid NOT NULL REFERENCES owner_crm(id),version integer NOT NULL,accepted_by text NOT NULL CHECK(length(accepted_by) BETWEEN 1 AND 200),accepted_at timestamptz NOT NULL,channel text NOT NULL CHECK(channel IN ('vk','telegram')),agreement_reference text NOT NULL UNIQUE CHECK(length(agreement_reference) BETWEEN 10 AND 200),verification_note text NOT NULL CHECK(length(verification_note) BETWEEN 10 AND 1000),billing_timezone text NOT NULL,billing_anchor timestamptz NOT NULL,idempotency_key uuid NOT NULL UNIQUE,payload_hash text NOT NULL,recorded_by uuid NOT NULL REFERENCES users(id),recorded_at timestamptz NOT NULL DEFAULT now(),audit_id uuid NOT NULL REFERENCES audit_events(id),CHECK(accepted_at<=recorded_at));
CREATE TRIGGER agreement_immutable BEFORE UPDATE OR DELETE ON founder_agreements FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
ALTER TABLE manual_subscription_payments ADD COLUMN agreement_id uuid NOT NULL REFERENCES founder_agreements(id);
CREATE TABLE owner_phone_reveals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owner_crm(id),actor_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL CHECK(length(reason) BETWEEN 10 AND 500),request_id uuid NOT NULL,audit_id uuid NOT NULL UNIQUE REFERENCES audit_events(id),revealed_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER phone_reveal_immutable BEFORE UPDATE OR DELETE ON owner_phone_reveals FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
CREATE TRIGGER review_original_immutable BEFORE UPDATE OF original_text ON account_reviews FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();

